{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://agentic-harness.local/contracts/authorized-file-read-request.v1.schema.json",
  "type": "object",
  "additionalProperties": false,
  "required": ["contractId", "payload"],
  "properties": {
    "contractId": { "const": "authorized-file-read-request.v1" },
    "payload": {
      "type": "object",
      "additionalProperties": false,
      "required": ["relativePath", "expectedSha256"],
      "properties": {
        "relativePath": { "type": "string", "minLength": 1 },
        "expectedSha256": { "type": "string", "pattern": "^sha256:[a-f0-9]{64}$" }
      }
    }
  }
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://agentic-harness.local/contracts/authorized-file-read-outcome.v2.schema.json",
  "oneOf": [
    { "$ref": "#/$defs/readEstablished" },
    { "$ref": "#/$defs/emptyFileEstablished" },
    { "$ref": "#/$defs/fileNotFound" },
    { "$ref": "#/$defs/readDenied" }
  ],
  "$defs": {
    "digest": { "type": "string", "pattern": "^sha256:[a-f0-9]{64}$" },
    "base64": {
      "type": "string",
      "pattern": "^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$"
    },
    "effectEvidenceBounded": {
      "type": "object",
      "additionalProperties": false,
      "required": ["providerCapabilityId", "bounded", "unchangedRoot", "interpretationMade", "effectLineage"],
      "properties": {
        "providerCapabilityId": { "const": "sda-governed-repository-observation-port.v1" },
        "bounded": { "const": true },
        "unchangedRoot": { "const": true },
        "interpretationMade": { "const": false },
        "effectLineage": { "type": "array", "minItems": 1, "items": { "type": "string", "minLength": 1 } }
      }
    },
    "effectEvidenceDenied": {
      "type": "object",
      "additionalProperties": false,
      "required": ["providerCapabilityId", "bounded", "unchangedRoot", "interpretationMade", "effectLineage"],
      "properties": {
        "providerCapabilityId": { "const": "sda-governed-repository-observation-port.v1" },
        "bounded": { "type": "boolean" },
        "unchangedRoot": { "const": true },
        "interpretationMade": { "const": false },
        "effectLineage": { "type": "array", "minItems": 1, "items": { "type": "string", "minLength": 1 } }
      }
    },
    "finding": {
      "type": "object",
      "additionalProperties": false,
      "required": ["code", "target", "message"],
      "properties": {
        "code": { "type": "string", "minLength": 1 },
        "target": { "type": "string", "minLength": 1 },
        "message": { "type": "string", "minLength": 1 }
      }
    },
    "readEstablished": {
      "type": "object",
      "additionalProperties": false,
      "required": ["contractId", "payload"],
      "properties": {
        "contractId": { "const": "authorized-file-read.v1" },
        "payload": {
          "type": "object",
          "additionalProperties": false,
          "required": ["relativePath", "bytesBase64", "byteLength", "sha256", "readDisposition", "effectEvidence"],
          "properties": {
            "relativePath": { "type": "string", "minLength": 1 },
            "bytesBase64": { "$ref": "#/$defs/base64" },
            "byteLength": { "type": "integer", "minimum": 1 },
            "sha256": { "$ref": "#/$defs/digest" },
            "readDisposition": { "const": "READ_ESTABLISHED" },
            "effectEvidence": { "$ref": "#/$defs/effectEvidenceBounded" }
          }
        }
      }
    },
    "emptyFileEstablished": {
      "type": "object",
      "additionalProperties": false,
      "required": ["contractId", "payload"],
      "properties": {
        "contractId": { "const": "authorized-empty-file-read.v1" },
        "payload": {
          "type": "object",
          "additionalProperties": false,
          "required": ["relativePath", "bytesBase64", "byteLength", "sha256", "readDisposition", "effectEvidence"],
          "properties": {
            "relativePath": { "type": "string", "minLength": 1 },
            "bytesBase64": { "const": "" },
            "byteLength": { "const": 0 },
            "sha256": { "const": "sha256:e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855" },
            "readDisposition": { "const": "EMPTY_FILE_ESTABLISHED" },
            "effectEvidence": { "$ref": "#/$defs/effectEvidenceBounded" }
          }
        }
      }
    },
    "fileNotFound": {
      "type": "object",
      "additionalProperties": false,
      "required": ["contractId", "payload"],
      "properties": {
        "contractId": { "const": "authorized-file-not-found.v1" },
        "payload": {
          "type": "object",
          "additionalProperties": false,
          "required": ["relativePath", "readDisposition", "findings", "effectEvidence"],
          "properties": {
            "relativePath": { "type": "string", "minLength": 1 },
            "readDisposition": { "const": "FILE_NOT_FOUND" },
            "findings": {
              "type": "array",
              "minItems": 1,
              "maxItems": 1,
              "items": {
                "allOf": [
                  { "$ref": "#/$defs/finding" },
                  { "properties": { "code": { "const": "FILE_NOT_FOUND" } } }
                ]
              }
            },
            "effectEvidence": { "$ref": "#/$defs/effectEvidenceBounded" }
          }
        }
      }
    },
    "readDenied": {
      "type": "object",
      "additionalProperties": false,
      "required": ["contractId", "payload"],
      "properties": {
        "contractId": { "const": "authorized-file-read-denied.v1" },
        "payload": {
          "type": "object",
          "additionalProperties": false,
          "required": ["relativePath", "readDisposition", "findings", "effectEvidence"],
          "properties": {
            "relativePath": { "type": "string", "minLength": 1 },
            "readDisposition": { "const": "READ_DENIED" },
            "findings": { "type": "array", "minItems": 1, "items": { "$ref": "#/$defs/finding" } },
            "effectEvidence": { "$ref": "#/$defs/effectEvidenceDenied" }
          }
        }
      }
    }
  }
}

{
  "capabilityId": "read-authorized-file",
  "name": "Read Authorized File",
  "mode": "capability",
  "userStory": {
    "actor": "caller",
    "intent": "resolve one digest-bound relative path beneath the provider-authorized root",
    "outcome": "receive exactly one non-empty, empty, missing, or denied read partition with attributable effect lineage"
  },
  "experience": {
    "experienceId": "partitioned-authorized-file-read-with-attributable-evidence.v2",
    "actor": "caller",
    "promise": "one admitted execution performs exactly one bounded governed repository observation and resolves every authorized-file state into one explicit terminal partition",
    "observableConditions": [
      {
        "conditionId": "relative-path-and-expected-digest-required"
      },
      {
        "conditionId": "provider-observation-is-bounded"
      },
      {
        "conditionId": "exact-bytes-and-physical-byte-length-preserved"
      },
      {
        "conditionId": "observed-digest-matches-request"
      },
      {
        "conditionId": "repository-remains-unchanged"
      },
      {
        "conditionId": "read-effect-lineage-is-attributable"
      },
      {
        "conditionId": "existing-empty-file-is-distinct-from-missing"
      },
      {
        "conditionId": "missing-file-is-distinct-from-provider-denial"
      },
      {
        "conditionId": "provider-findings-are-preserved-on-denial"
      }
    ]
  },
  "rootScenarioId": "read-authorized-file"
}

