    assert.deepEqual(held.executions.map((item) => item.scenarioId), ["route", "held"]);
    assert.deepEqual(held.graphExecution.edgeTestimony.map((item) => item.edgeId), ["route-hold"]);
  } finally {
    fs.rmSync(directory, { recursive: true, force: true });
  }
});

